#include <stdlib.h>
#include <stdio.h>
#include <string.h>
static void f(char*s,int pos,long val,long last,char*buf,int len,long target,char***o,int*c,int*cap){if(!s[pos]){if(val==target){buf[len]=0;if(*c==*cap){*cap*=2;*o=realloc(*o,*cap*sizeof(char*));}(*o)[(*c)++]=strdup(buf);}return;}long n=0;int start=pos;for(int i=pos;s[i];i++){if(i>start&&s[start]=='0')break;n=n*10+s[i]-'0';int old=len;if(pos==0){memcpy(buf+len,s+pos,i-pos+1);len+=i-pos+1;f(s,i+1,n,n,buf,len,target,o,c,cap);}else{buf[len++]='+';memcpy(buf+len,s+pos,i-pos+1);len+=i-pos+1;f(s,i+1,val+n,n,buf,len,target,o,c,cap);len=old;buf[len++]='-';memcpy(buf+len,s+pos,i-pos+1);len+=i-pos+1;f(s,i+1,val-n,-n,buf,len,target,o,c,cap);len=old;buf[len++]='*';memcpy(buf+len,s+pos,i-pos+1);len+=i-pos+1;f(s,i+1,val-last+last*n,last*n,buf,len,target,o,c,cap);}len=old;}}char** addOperators(char*s,int target,int*rs){int cap=16,c=0;char**o=malloc(cap*sizeof(char*));char*buf=malloc(strlen(s)*2+2);f(s,0,0,0,buf,0,target,&o,&c,&cap);free(buf);*rs=c;return o;}
